#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum CacheOnlyRefusal {
    ManifestMiss,
    EntryUnavailable,
}

/// The cache-only choke point. The continuation contains every operation that
/// may enter the ordinary load-or-solve path, so a refusal structurally occurs
/// before that operation rather than being inferred from a later receipt.
fn cache_only_before_solve<T>(
    allowed: Result<(), CacheOnlyRefusal>,
    proceed: impl FnOnce() -> T,
) -> Result<T, CacheOnlyRefusal> {
    allowed?;
    Ok(proceed())
}

fn accepted_cache_manifest_contains(
    manifest: &str,
    program: &str,
    fingerprint: &str,
) -> Result<bool, String> {
    let mut lines = manifest.lines();
    let header = lines
        .next()
        .ok_or_else(|| "accepted cache manifest is empty".to_owned())?;
    let columns = header
        .split('\t')
        .enumerate()
        .map(|(index, name)| (name, index))
        .collect::<std::collections::BTreeMap<_, _>>();
    let program_column = columns
        .get("program")
        .copied()
        .ok_or_else(|| "accepted cache manifest lacks program".to_owned())?;
    let fingerprint_column = columns
        .get("fingerprint")
        .or_else(|| columns.get("new_fingerprint"))
        .copied()
        .ok_or_else(|| "accepted cache manifest lacks fingerprint/new_fingerprint".to_owned())?;
    Ok(lines.any(|line| {
        let fields = line.split('\t').collect::<Vec<_>>();
        fields.get(program_column) == Some(&program)
            && fields.get(fingerprint_column) == Some(&fingerprint)
    }))
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct StandingCensusLaunchRecipe {
    profile: &'static str,
    memory_mib: u64,
    timeout_secs: u64,
    attestation: &'static str,
}

impl StandingCensusLaunchRecipe {
    /// Resolve one registered corpus program through the recipe-owned file
    /// map.  Callers hand this either the selected substrate root (two-root
    /// checks) or the workspace root (ordinary launches); no representative
    /// may guess `lib.rs`.
    fn program_file(
        self,
        corpus_root: &std::path::Path,
        program: CorpusProgram,
    ) -> std::path::PathBuf {
        let _ = self;
        corpus_root.join(program.name).join(program.lib_root)
    }

    fn workspace_program_file(
        self,
        workspace_root: &std::path::Path,
        program: CorpusProgram,
    ) -> std::path::PathBuf {
        self.program_file(&workspace_root.join(substrate_dir()), program)
    }

    fn common_child_env(self, cache_dir: &std::path::Path) -> Vec<(&'static str, String)> {
        vec![
            ("CRAT_BO_CACHE", "1".to_owned()),
            ("CRAT_BO_CACHE_DIR", cache_dir.display().to_string()),
            ("CRAT_BO_A5_ATTESTATION", self.attestation.to_owned()),
            ("CRAT_BOC1_MEM_MB", self.memory_mib.to_string()),
        ]
    }

    fn child_env(
        self,
        cache_dir: &std::path::Path,
        artifact_dir: &std::path::Path,
        code_frame: &str,
    ) -> Vec<(&'static str, String)> {
        let mut env = self.common_child_env(cache_dir);
        env.extend([
            ("CRAT_E2_ARTIFACT_DIR", artifact_dir.display().to_string()),
            ("CRAT_E2_CODE_FRAME", code_frame.to_owned()),
            ("CRAT_E2_CARGO_PROFILE", self.profile.to_owned()),
        ]);
        env
    }

    fn box_child_env(
        self,
        cache_dir: &std::path::Path,
        artifact_dir: &std::path::Path,
        code_frame: &str,
    ) -> Vec<(&'static str, String)> {
        let mut env = self.common_child_env(cache_dir);
        env.extend([
            ("CRAT_E1_ARTIFACT_DIR", artifact_dir.display().to_string()),
            (
                "CRAT_BOX_CENSUS_ARTIFACT_DIR",
                artifact_dir.display().to_string(),
            ),
            ("CRAT_BOX_CODE_FRAME", code_frame.to_owned()),
            ("CRAT_BOX_CARGO_PROFILE", self.profile.to_owned()),
        ]);
        env
    }

    fn raw_boundary_child_env(
        self,
        cache_dir: &std::path::Path,
        artifact_dir: &std::path::Path,
        code_frame: &str,
    ) -> Vec<(&'static str, String)> {
        let mut env = self.common_child_env(cache_dir);
        let cache_manifest = std::env::var("CRAT_RAW_BOUNDARY_CACHE_MANIFEST")
            .expect("raw-boundary parent requires accepted cache manifest");
        let exposure_input = std::env::var("CRAT_RAW_BOUNDARY_EXPOSURE_INPUT")
            .expect("raw-boundary parent requires configured exposure input");
        let exposure_input_sha256 = std::env::var("CRAT_RAW_BOUNDARY_EXPOSURE_INPUT_SHA256")
            .expect("raw-boundary parent requires configured exposure input digest");
        env.extend([
            (
                "CRAT_RAW_BOUNDARY_ARTIFACT_DIR",
                artifact_dir.display().to_string(),
            ),
            ("CRAT_RAW_BOUNDARY_CODE_FRAME", code_frame.to_owned()),
            ("CRAT_RAW_BOUNDARY_CARGO_PROFILE", self.profile.to_owned()),
            ("CRAT_RAW_BOUNDARY_CACHE_MANIFEST", cache_manifest),
            ("CRAT_RAW_BOUNDARY_EXPOSURE_INPUT", exposure_input),
            (
                "CRAT_RAW_BOUNDARY_EXPOSURE_INPUT_SHA256",
                exposure_input_sha256,
            ),
        ]);
        for key in [
            "CRAT_RAW_BOUNDARY_UNIFIED_CONTROL",
            "CRAT_RAW_BOUNDARY_DIAGNOSTIC_CONTROL",
        ] {
            if let Ok(value) = std::env::var(key) {
                env.push((key, value));
            }
        }
        env
    }
}

const STANDING_CENSUS_LAUNCH_RECIPE: StandingCensusLaunchRecipe = StandingCensusLaunchRecipe {
    profile: "release",
    memory_mib: 49_152,
    timeout_secs: 14_400,
    attestation: "frozen_benchmark_graph",
};

fn e2_resource_bound_non_citable_reason(
    configured_mib: Option<&str>,
    effective_mib: Option<&str>,
) -> Option<&'static str> {
    let effective_mib = effective_mib.and_then(|value| value.parse::<u64>().ok());
    if effective_mib.is_none_or(|value| value < STANDING_CENSUS_LAUNCH_RECIPE.memory_mib) {
        return Some("insufficient-memory-bound");
    }
    let configured_mib = configured_mib.and_then(|value| value.parse::<u64>().ok());
    if configured_mib != Some(STANDING_CENSUS_LAUNCH_RECIPE.memory_mib) {
        return Some("configured-memory-bound-mismatch");
    }
    None
}

