// Worker (one program, one mode, one process).
// ---------------------------------------------------------------------------

#[test]
#[ignore = "C1-lite worker: spawned per program by boc1_corpus (needs CRAT_BOC1_INPUT)"]
fn boc1_run_one() {
    use std::{path::Path, time::Instant};

    let Ok(input) = std::env::var("CRAT_BOC1_INPUT") else {
        eprintln!("BOC1 worker: CRAT_BOC1_INPUT unset; no-op (did you mean boc1_corpus?)");
        return;
    };
    let mode = std::env::var("CRAT_BOC1_MODE").unwrap_or_else(|_| "bo".to_string());
    let name = std::env::var("CRAT_BOC1_NAME").unwrap_or_else(|_| "unnamed".to_string());

    // §NB5-Z (2026-07-17): pin z3's random seeds for the BO sweep — HERE, at the ignored per-program
    // worker entry, before ANY z3 op in this fresh process. z3 0.19's `Context` is a per-thread
    // `thread_local!` built once as `Context::new(&Config::new())` and reused; `set_global_param` only
    // feeds a context created AFTER it fires, so the pin must precede this process's first z3 touch.
    // This is the ONLY correct site: `run_bo` and `solver.rs` are both reached by NON-ignored suite
    // tests (e.g. `origins_runs_once_per_program` calls `run_bo` directly), so pinning there would leak
    // this PROCESS-GLOBAL param into the PARALLEL test runner (Codex NB5-Z finding). `boc1_run_one` is
    // `#[ignore]` and spawned one-per-program as a fresh single-threaded process, so the pin fires once
    // per program and never under the parallel suite. The registered ownership-yield `prod-own`
    // worker is solver-backed, so it shares the same explicit seed contract; the frozen
    // production-borrow `prod` reference remains untouched. Expected behavior-neutral (z3's default
    // seed is already 0); the value is recorded through each solver-backed row's
    // `z3_full_version` stamp.
    if matches!(
        mode.as_str(),
        "bo" | "prod-own"
            | "prod-precision"
            | "prod-box"
            | "selector-core"
            | "selector-necessity"
            | "a4-probe"
            | "a4-source-census"
            | "a5-p1"
            | "a5-batch-model"
            | "copy-lend-funnel"
            | "copy-lend-funnel-subjects"
            | "kind-equate-core"
            | "s23-discover"
            | "s23-probe"
            | "t1-origin-caller"
            | "e1-revert-census"
            | "e2-fn-census"
            | "box-facts"
            | "box-census"
            | "raw-boundary-census"
    ) || mode.starts_with("selector-detail-")
    {
        z3::set_global_param("smt.random_seed", "0");
        z3::set_global_param("sat.random_seed", "0");
    }

    if mode == "m1-diag" {
        let mut row = run::run_m1_diag(Path::new(&input));
        row.set("program", name.clone());
        println!("{}", report::to_kv_line(&row));
        return;
    }

    if mode == "m1-emit" {
        let mut row = run::run_m1_emit(Path::new(&input));
        row.set("program", name.clone());
        println!("{}", report::to_kv_line(&row));
        return;
    }

    if mode == "e1-revert-census" {
        let mut row = run::run_e1_revert_census(Path::new(&input));
        row.set("program", name.clone());
        row.set("mode", "e1-revert-census");
        println!("{}", report::to_kv_line(&row));
        return;
    }

    if mode == "e2-fn-census" {
        let mut row = run::run_e2_fn_census(Path::new(&input));
        row.set("program", name.clone());
        row.set("mode", "e2-fn-census");
        println!("{}", report::to_kv_line(&row));
        return;
    }

    if mode == "box-census" {
        let mut row = run::run_box_census(Path::new(&input));
        row.set("program", name.clone());
        row.set("mode", "box-census");
        println!("{}", report::to_kv_line(&row));
        return;
    }

    if mode == "raw-boundary-census" {
        let mut row = run::run_raw_boundary_census(Path::new(&input));
        row.set("program", name.clone());
        row.set("mode", "raw-boundary-census");
        println!("{}", report::to_kv_line(&row));
        return;
    }

    let t0 = Instant::now();
    let result = ::utils::compilation::run_compiler_on_path(Path::new(&input), |tcx| {
        let t_tcx = t0.elapsed();
        match mode.as_str() {
            // §HLZ-PORT attribution (§5.6 item 1) — env-gated E-R4 loan-identity dump. Default off,
            // so the sweep contract is unchanged; when set, the SAME `run_bo` runs inside
            // `with_bo_export` and its loan identities are written as TSV. Test-only harness file.
            "bo" if std::env::var_os("CRAT_BOC1_ER4_OUT").is_some() => {
                let path = std::env::var("CRAT_BOC1_ER4_OUT").expect("CRAT_BOC1_ER4_OUT");
                let ((row, trace), export) =
                    crate::analyses::borrow_ownership::export::with_bo_export(|| {
                        crate::analyses::borrow_ownership::borrow_verify::with_mode_a_commit_trace(
                            || run::run_bo(tcx, t_tcx),
                        )
                    });
                // §HLZ-PORT §5.6 item 1 — the Mode-A commit trace, in the loop's natural commit
                // order. Round 0 agrees between the arms (identical conflict edges at all-Ref
                // candidacy), so the +15 commits are a LOOP-PATH effect and this is where they
                // become visible per round.
                {
                    let mut t = String::from("round\ttarget\tconflict\n");
                    for ev in &trace {
                        t.push_str(&format!(
                            "{}\t{:?}\t{:?}\n",
                            ev.round, ev.target, ev.conflict
                        ));
                    }
                    std::fs::write(format!("{path}.commits"), t)
                        .unwrap_or_else(|e| panic!("ER4 commit trace: {e}"));
                }
                let mut out = String::from(
                    "fn\tborrower\tcallee_or_owner\tplace\tlocation\tkind\tclass\tinvalid\n",
                );
                let mut rows: Vec<String> = export
                    .loans
                    .iter()
                    .map(|loan| {
                        let borrower = match &loan.key.borrower {
                            crate::analyses::borrow_ownership::export::BorrowerKind::Assign {
                                owner,
                            } => format!("assign\t{owner:?}"),
                            crate::analyses::borrow_ownership::export::BorrowerKind::CallArg {
                                callee,
                                arg_index,
                            } => format!("callarg\tcallee={callee}:arg={arg_index}"),
                        };
                        format!(
                            "{}\t{}\t{:?}\t{:?}\t{:?}\t{:?}\t{}",
                            tcx.def_path_str(loan.key.fn_did.to_def_id()),
                            borrower,
                            loan.key.place,
                            loan.key.location,
                            loan.kind,
                            loan.class,
                            loan.invalid,
                        )
                    })
                    .collect();
                rows.sort();
                for r in rows {
                    out.push_str(&r);
                    out.push('\n');
                }
                // The `invalid` column above CANNOT carry a positive: it reads the FINAL,
                // already-repaired round (the 2026-08-04 CallArg record's own instrument control
                // fired on exactly this, and it discarded the data). The observation point that
                // record adopted instead is the round-0 conflict-edge set at an ALL-Ref
                // candidacy, so the dump carries that too — an `issuer=None` edge is the
                // owner-less/`CallArg` signature.
                {
                    use rustc_middle::mir::Local;
                    use rustc_span::def_id::LocalDefId;
                    let program = collect_program(tcx);
                    let edges = crate::analyses::borrow_ownership::borrow_engine::borrow_conflicts(
                        &program,
                        |_: LocalDefId| |_: Local| true,
                        |_: LocalDefId| |_: Local| true,
                    );
                    let mut lines: Vec<String> = edges
                        .iter()
                        .flat_map(|(did, es)| {
                            let name = tcx.def_path_str(did.to_def_id());
                            es.iter().map(move |e| {
                                let mut req: Vec<String> =
                                    e.requirers.iter().map(|o| format!("{o:?}")).collect();
                                req.sort();
                                format!(
                                    "{name}\t{}\t{req:?}",
                                    match e.issuer {
                                        Some(o) => format!("{o:?}"),
                                        None => "OWNERLESS".to_string(),
                                    }
                                )
                            })
                        })
                        .collect();
                    lines.sort();
                    let mut edge_out = String::from("fn\tissuer\trequirers\n");
                    for l in lines {
                        edge_out.push_str(&l);
                        edge_out.push('\n');
                    }
                    std::fs::write(format!("{path}.edges"), edge_out)
                        .unwrap_or_else(|e| panic!("ER4 edge dump: {e}"));
                }
                // §8 landing-gate evidence: for every function, its `arg_count` and the
                // source-level `var_debug_info` name of each local that has one. A moved local is
                // a PARAMETER iff its index <= arg_count (that is the W14 exposure population),
                // and it has a SOURCE DECLARATION iff it appears here with a name (that is what
                // the official declaration metric counts). Both questions answered from MIR.
                {
                    let mut lines: Vec<String> = Vec::new();
                    for &f in &collect_program(tcx).functions {
                        let body = tcx.mir_drops_elaborated_and_const_checked(f).borrow();
                        let name = tcx.def_path_str(f.to_def_id());
                        let mut named: Vec<String> = body
                            .var_debug_info
                            .iter()
                            .filter_map(|vdi| match vdi.value {
                                rustc_middle::mir::VarDebugInfoContents::Place(pl) => {
                                    Some(format!("_{}={}", pl.local.index(), vdi.name))
                                }
                                _ => None,
                            })
                            .collect();
                        named.sort();
                        lines.push(format!(
                            "{name}\targ_count={}\tlocals={}\tnamed={}",
                            body.arg_count,
                            body.local_decls.len(),
                            named.join(",")
                        ));
                    }
                    lines.sort();
                    std::fs::write(format!("{path}.locals"), lines.join("\n") + "\n")
                        .unwrap_or_else(|e| panic!("ER4 locals dump: {e}"));
                }
                std::fs::write(&path, out).unwrap_or_else(|e| panic!("ER4 dump {path}: {e}"));
                row
            }
            "bo" => run::run_bo(tcx, t_tcx),
            "prod" => run::run_prod(tcx, t_tcx),
            "prod-own" => run::run_prod_ownership(tcx, t_tcx),
            "prod-precision" => run::run_prod_ownership(tcx, t_tcx),
            "prod-box" => run::run_prod_box(tcx, t_tcx),
            "m1-census" => run::run_m1_census(tcx, t_tcx),
            "e1-cache-preflight" => run::run_e1_cache_preflight(tcx, t_tcx),
            "box-facts" => run::run_box_fact_worker(tcx, t_tcx),
            "substrate-sanity" => run::run_substrate_sanity(tcx, t_tcx),
            "free-overlap" => run::run_free_overlap(tcx, t_tcx),
            "use-census" => run::run_use_census(tcx, t_tcx),
            "m1-recon" => run::run_m1_recon(tcx, t_tcx),
            "m1-editdump" => run::run_m1_editdump(tcx, t_tcx),
            "a4-probe" => a4_measurement::run_probe_worker(tcx, t_tcx),
            "a4-source-census" => a4_source_census::run_worker(tcx, t_tcx),
            "a5-p1" => a5_measurement::run_worker(tcx, t_tcx),
            "a5-batch-model" => run::run_a5_batch_model(tcx, t_tcx),
            "a16-return-kind-exposure" => a16_return_kind_exposure::run_worker(tcx, t_tcx),
            "a5-w14-drift-trace" => a5_measurement::run_w14_drift_trace_worker(tcx, t_tcx),
            "a5-production-site-join" => {
                a5_measurement::run_production_site_join_worker(tcx, t_tcx)
            }
            "a5-site-scope-repartition" => {
                a5_measurement::run_site_scope_repartition_worker(tcx, t_tcx)
            }
            "copy-lend-funnel" => {
                crate::analyses::borrow_ownership::construction::CopyLendMode::LendArm
                    .with_override(|| copy_lend_funnel::run_worker(tcx, t_tcx))
            }
            "copy-lend-funnel-subjects" => {
                crate::analyses::borrow_ownership::construction::CopyLendMode::LendArm
                    .with_override(|| copy_lend_funnel::run_subject_worker(tcx, t_tcx))
            }
            "p-b" => p_b_measurement::run_worker(tcx, t_tcx),
            "kind-equate-core" => kind_equate_core_census::run_worker(tcx, t_tcx),
            "s23-discover" => s23_measurement::run_discovery_worker(tcx, t_tcx),
            "s23-probe" => s23_measurement::run_probe_worker(tcx, t_tcx),
            "t1-origin-caller" => t1_origin_caller_probe::run_worker(tcx, t_tcx),
            "t1-characterize" => t1_origin_caller_probe::run_characterization_worker(tcx, t_tcx),
            "selector-core" => run::run_selector_core(tcx, t_tcx),
            "selector-necessity" => run::run_selector_necessity(tcx, t_tcx),
            detail if detail.starts_with("selector-detail-") => {
                run::run_selector_core_detail(tcx, t_tcx)
            }
            other => panic!("unknown CRAT_BOC1_MODE `{other}`"),
        }
    });

    let mut row = match result {
        Ok(row) => row,
        Err(_fatal) => {
            // rustc reported fatal diagnostics on stderr (in the child log).
            let mut row = report::Row::default();
            row.set("status", "compile-error");
            row.set("t_total_s", format!("{:.3}", t0.elapsed().as_secs_f64()));
            row
        }
    };
    // Prepend identity keys so every sentinel line is self-describing.
    let mut ident = report::Row::default();
    ident.set("program", &name);
    ident.set("mode", &mode);
    ident.0.extend(row.0.drain(..));
    println!("{}", report::to_kv_line(&ident));

    // T1.2b — the worker PROCESS fails when the reconciliation does.
    //
    // Deliberately scoped to `m1-recon`. Applying it to every mode would change
    // how the solver sweeps treat `compile-error` and `decline`, silently
    // shifting results the ledger already cites — a blast radius well outside
    // this repair.
    //
    // The panic comes AFTER the sentinel line, so a failing program still
    // reports its row and the driver still sees full incidence.
    if mode == "m1-recon" {
        let status = ident.get("status").unwrap_or("missing");
        assert_eq!(
            status, "ok",
            "m1-recon: {name} did not reconcile (status={status}). The verdict \
             is the process result — a run that reports FAIL and exits green is \
             report-only, which is exactly the defect this scoping repairs."
        );
    }
}

// ---------------------------------------------------------------------------
// Orchestrator (spawns one worker process per program × mode).
// ---------------------------------------------------------------------------

/// Evaluation corpus under `benchmarks/rs-crown/`, smallest-first by measured Rust SLOC.
/// SLOC is cloc 2.00's `code` total over each program's `.rs` files, excluding `build.rs` and
/// `target/`, with duplicate files counted. The development boundary is inclusive of brotli.
#[derive(Clone, Copy, Debug)]
struct CorpusProgram {
    name: &'static str,
    lib_root: &'static str,
    sloc: usize,
}

/// The substrate directory M1 measures on, selected by `CRAT_BOC1_SUBSTRATE`.
///
/// - `derived` (**the default, and the substrate of record**) —
///   `benchmarks/rs-crown-derived`: the 20 programs after
///   `expand → extern → preprocess`, produced by
///   `docs/agents/tools/derive_substrate.py`, digest
///   `db96829b5c2b0db28fb4bb9ddd3d32901b5d4e6e4134da07ada0d513d94eb4c6`.
/// - `raw` — `benchmarks/rs-crown`, the c2rust output as shipped. Retained so
///   the raw era stays reproducible; **not** what M1 reports.
///
/// The default flipped with the 2026-08-06 substrate migration. The tool's real
/// input is the post-pre-pass form, so measuring the raw form measures a
/// configuration nobody runs — and one the analysis sees *less* of: on raw,
/// c2rust's per-module `extern "C"` blocks put intra-crate function references
/// behind foreign `DefId`s, so A1's `referenced` set under-fires and 291
/// parameters were decided `Ref` while the crate held fn-pointer casts of their
/// functions. See `docs/agents/2026-08-06-substrate-of-record.md`.
///
/// **One place.** Thirteen call sites reach the corpus, all through
/// `input_path`, so the substrate is chosen here and nowhere else; a second
/// notion of "which tree is this" would eventually disagree with this one and
/// the disagreement would surface as numbers measured on a mixture.
///
/// An unrecognized value is a hard error rather than a fallback: a typo that
/// silently measured the other substrate is exactly the failure this selector
/// exists to prevent.
pub(crate) fn substrate_dir() -> &'static str {
    substrate_dir_of(std::env::var("CRAT_BOC1_SUBSTRATE").ok().as_deref())
}

/// The selection itself, as a pure function of the setting.
///
/// Split out from the env read so it can be witnessed without `set_var`:
/// the suite runs its tests as threads of one process, so a test that mutated
/// this variable would be mutating it for every concurrently running test.
pub(crate) fn substrate_dir_of(setting: Option<&str>) -> &'static str {
    match setting {
        None | Some("derived") => "benchmarks/rs-crown-derived",
        Some("raw") => "benchmarks/rs-crown",
        other => panic!(
            "CRAT_BOC1_SUBSTRATE must be `raw` or `derived`, got {other:?}; \
             an unrecognized value is never silently treated as either"
        ),
    }
}

/// Guard for sweeps whose expectations are still **raw-form era** constants.
///
/// The 2026-08-06 substrate migration re-derived what it measured — the L2 RED
/// base, the recon population pins, the emit counters. It did **not** re-run
/// the CROWN-projection, pairwise-family-removal, ownership-diagnostic or
/// selector sweeps, whose pinned totals (`n_ref = 52,810`, `n_own = 230`,
/// `sources_leaked_sel = 114`, …) were all measured on the raw tree.
///
/// Those constants are not wrong; they are *raw-era*. Left unguarded, running
/// one of these sweeps under the new default would compare derived numbers
/// against raw pins and report a drift that is really a substrate mismatch.
/// This turns that into an immediate, explanatory stop.
///
/// **This is a stated scope boundary, not a silent cap:** re-pinning these
/// needs the sweeps re-run, which is a separate commission.
#[cfg(test)]
fn assert_raw_era_substrate(sweep: &str) {
    assert_eq!(
        substrate_dir(),
        "benchmarks/rs-crown",
        "{sweep} carries RAW-FORM ERA expectations and must run with \
         CRAT_BOC1_SUBSTRATE=raw. Its totals were measured before the \
         2026-08-06 substrate migration and have not been re-derived on the \
         derived tree; see docs/agents/2026-08-06-substrate-of-record.md."
    );
}

impl CorpusProgram {
    fn input_path(self, root: &std::path::Path) -> std::path::PathBuf {
        root.join(substrate_dir())
            .join(self.name)
            .join(self.lib_root)
    }
}

