/// The substrate selector: both accepted settings, and the refusal to guess.
///
/// The unrecognized-value arm is the load-bearing one. A selector that fell
/// back to `raw` on a typo would report numbers measured on the OLD substrate
/// under the new substrate's name, and nothing downstream could tell.
/// The certified inventory refuses to be read on the substrate of record.
///
/// The deferral ruling says consuming it against the derived substrate must
/// FAIL LOUDLY until it is re-derived. That is a claim about behaviour, so it
/// is witnessed rather than asserted in prose: the suite runs with
/// `CRAT_BOC1_SUBSTRATE` unset, which is the derived tree, and `targets()` is
/// the single reader every consumer passes through.
///
/// The base is deliberately NOT guarded — it re-anchored and stays live as the
/// official-metric regression guard — so this also pins the split.
#[test]
fn the_certified_inventory_refuses_the_derived_substrate() {
    assert_eq!(
        substrate_dir(),
        "benchmarks/rs-crown-derived",
        "suite default"
    );

    let read = std::panic::catch_unwind(l2_red_gate::targets);
    assert!(
        read.is_err(),
        "the raw-era certified inventory must not be readable on the substrate \
         of record; it is deferred to M1-close, not silently reusable"
    );

    // The base is the control: same fixture module, not guarded, still live.
    let bases = l2_red_gate::bases();
    assert_eq!(bases.len(), 20);
    assert_eq!(bases.iter().map(|b| b.n_ref).sum::<usize>(), 50_334);
}

#[test]
fn the_substrate_selector_names_both_trees_and_refuses_to_guess() {
    // The DEFAULT is the substrate of record. This assertion is the migration:
    // an unset variable must reach the derived tree, not the raw one.
    assert_eq!(substrate_dir_of(None), "benchmarks/rs-crown-derived");
    assert_eq!(
        substrate_dir_of(Some("derived")),
        "benchmarks/rs-crown-derived"
    );
    assert_eq!(substrate_dir_of(Some("raw")), "benchmarks/rs-crown");

    for bad in ["", "Derived", "rs-crown-derived", "1"] {
        let refused = std::panic::catch_unwind(|| substrate_dir_of(Some(bad))).is_err();
        assert!(refused, "{bad:?} must be refused, never guessed");
    }
}

#[test]
fn rs_crown_catalog_contract() {
    let expected = [
        ("bst", "lib.rs", 102),
        ("avl", "lib.rs", 133),
        ("ht", "lib.rs", 251),
        ("libcsv", "lib.rs", 963),
        ("buffer", "lib.rs", 1_104),
        ("quadtree", "lib.rs", 1_184),
        ("urlparser", "lib.rs", 1_363),
        ("robotfindskitten", "lib.rs", 1_476),
        ("rgba", "lib.rs", 1_823),
        ("genann", "lib.rs", 2_302),
        ("libtree", "lib.rs", 2_578),
        ("json.h", "lib.rs", 3_847),
        ("binn", "lib.rs", 4_413),
        ("libzahl", "lib.rs", 4_642),
        ("lil", "lib.rs", 5_638),
        ("heman", "lib.rs", 13_750),
        ("bzip2", "c2rust-lib.rs", 13_967),
        ("lodepng", "lib.rs", 14_140),
        ("tulipindicators", "c2rust-lib.rs", 19_760),
        ("brotli", "lib.rs", 537_692),
    ];
    let actual: Vec<_> = CORPUS
        .iter()
        .map(|program| (program.name, program.lib_root, program.sloc))
        .collect();

    assert_eq!(CORPUS.len(), 20);
    assert_eq!(actual.as_slice(), expected.as_slice());
    assert_eq!(BROTLI_SLOC, 537_692);
    assert!(!is_resource_deferred(BROTLI_SLOC));
    assert!(is_resource_deferred(BROTLI_SLOC + 1));
    assert!(
        CORPUS
            .iter()
            .all(|program| !is_resource_deferred(program.sloc))
    );

    let root = orchestrate::workspace_root();
    for program in CORPUS {
        let input = program.input_path(&root);
        assert!(
            input.is_file(),
            "missing rs-crown input for {}: {input:?}",
            program.name
        );
        assert!(input.starts_with(root.join(substrate_dir())));

        let expected_root = if matches!(program.name, "bzip2" | "tulipindicators") {
            "c2rust-lib.rs"
        } else {
            "lib.rs"
        };
        assert_eq!(
            input.file_name().and_then(|name| name.to_str()),
            Some(expected_root)
        );
    }
}

#[test]
fn pairwise_joint_anchor_covers_exact_catalog() {
    assert_eq!(
        PAIRWISE_EXPECTED_JOINT_BY_PROGRAM
            .iter()
            .map(|(program, _)| *program)
            .collect::<std::collections::BTreeSet<_>>(),
        CORPUS
            .iter()
            .map(|program| program.name)
            .collect::<std::collections::BTreeSet<_>>()
    );
    assert_eq!(
        PAIRWISE_EXPECTED_JOINT_BY_PROGRAM
            .iter()
            .map(|(_, rows)| *rows)
            .sum::<usize>(),
        63
    );
}

